// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.costimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport timber.log.Timberimport java.time.Instantimport java.time.LocalDateimport java.time.ZoneIdimport java.util.concurrent.ConcurrentHashMapimport java.util.concurrent.atomic.AtomicLongimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — LLM cost tracker. * * Tracks per-provider token usage and USD cost. Enforces the user's monthly * LLM budget cap — when exceeded, [checkBudget] returns Failure and the cloud * layer refuses to make new calls. * * ## What's Tracked * *   - Per provider: input tokens, output tokens, USD spent (this month) *   - Per provider: total calls, success/failure counts *   - Aggregate: total USD spent this month across all providers * * ## Monthly Reset * * On the 1st of each month (in the user's timezone), the tracker automatically * resets all monthly counters. This is checked lazily on every [recordUsage] * and [checkBudget] call — no background job needed. * * ## Budget Enforcement * * The user sets a monthly LLM budget in Settings → Privacy → Monthly Budget * (default $5.00 per [com.roshan.persona.brain.context.UserContext.monthlyLlmBudgetUsd]). * * [checkBudget] returns Failure if the projected cost (current spent + estimated * new call cost) would exceed the budget. The cloud layer MUST call this before * every cloud LLM call. * * ## Persistence * * This in-memory implementation is for Module 2 standalone + tests. Real * persistence (Room-backed) ships in :feature:memory (Module 3) via the * `llm_usage` table with monthly partitioning. * * @see <a href="docs/spec/module2-spec-review.pdf">§8.4 Cost Tracking</a> */@Singletonclass LlmCostTracker @Inject constructor(    private val userTimezone: ZoneId,) {    private val monthlyUsageByProvider = ConcurrentHashMap<String, MonthlyUsage>()    private val totalCalls = AtomicLong(0L)    private val successfulCalls = AtomicLong(0L)    private val failedCalls = AtomicLong(0L)    @Volatile private var currentMonthYear: String = computeMonthYear(Instant.now())    /**     * Record usage from a completed LLM call.     *     * @param providerId which provider was used     * @param inputTokens number of input (prompt) tokens     * @param outputTokens number of output (generated) tokens     * @param costUsd actual USD cost (computed by caller via     *   [com.roshan.persona.brain.llm.provider.CloudProviderConfig.computeCostUsd])     * @param success whether the call succeeded     * @return Success with updated usage, or Failure (never fails in practice)     */    fun recordUsage(        providerId: String,        inputTokens: Int,        outputTokens: Int,        costUsd: Float,        success: Boolean,    ): Result<MonthlyUsage> {        val correlationId = CorrelationId.generate()        // Lazy monthly reset check        checkAndResetIfNewMonth()        val usage = monthlyUsageByProvider.compute(providerId) { _, current ->            (current ?: MonthlyUsage(providerId = providerId, monthYear = currentMonthYear))                .addUsage(                    inputTokens = inputTokens,                    outputTokens = outputTokens,                    costUsd = costUsd,                    success = success,                )        }        if (usage == null) {            // compute() returned null — only possible if the mapping function returned null,            // which our implementation above never does. Defensive guard.            return Result.Failure(                error = AppError.Unknown(),                correlationId = correlationId,                durationNanos = 0,            )        }        totalCalls.incrementAndGet()        if (success) successfulCalls.incrementAndGet() else failedCalls.incrementAndGet()        Timber.tag("NOUS.L4").v(            "Recorded: provider=%s in=%d out=%d cost=\$%.4f success=%s (monthly total: \$%.2f)",            providerId, inputTokens, outputTokens, costUsd, success,            getTotalSpentThisMonth(),        )        return Result.Success(usage, correlationId, 0)    }    /**     * Check whether a new call with [estimatedCostUsd] would exceed the     * monthly budget.     *     * Called by [com.roshan.persona.brain.llm.layer.CloudLlmLayer] BEFORE     * every cloud LLM call. If this returns Failure, the layer refuses to     * make the call and returns a budget-exceeded error to the user.     *     * @param monthlyBudgetUsd user's monthly LLM budget cap     * @param estimatedCostUsd estimated cost of the new call     * @return Success if within budget, Failure if would exceed     */    fun checkBudget(        monthlyBudgetUsd: Float,        estimatedCostUsd: Float,    ): Result<Unit> {        checkAndResetIfNewMonth()        val currentSpent = getTotalSpentThisMonth()        val projected = currentSpent + estimatedCostUsd        if (projected > monthlyBudgetUsd) {            Timber.tag("NOUS.L4").w(                "Budget exceeded: \$%.2f + \$%.4f > \$%.2f",                currentSpent, estimatedCostUsd, monthlyBudgetUsd,            )            return Result.Failure(                error = AppError.Configuration.BudgetExceeded(                    monthlyBudgetUsd = monthlyBudgetUsd,                    monthlySpentUsd = currentSpent,                ),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        return Result.Success(Unit, CorrelationId.generate(), 0)    }    /**     * Total USD spent across all providers in the current month.     */    fun getTotalSpentThisMonth(): Float {        checkAndResetIfNewMonth()        return monthlyUsageByProvider.values.sumOf { it.costUsd.toDouble() }.toFloat()    }    /**     * Get usage for a specific provider in the current month.     */    fun getUsageForProvider(providerId: String): MonthlyUsage? {        checkAndResetIfNewMonth()        return monthlyUsageByProvider[providerId]    }    /**     * Get usage for all providers in the current month.     */    fun getAllUsage(): List<MonthlyUsage> {        checkAndResetIfNewMonth()        return monthlyUsageByProvider.values.toList().sortedByDescending { it.costUsd }    }    /**     * Aggregate stats across all providers and time.     */    fun getAggregateStats(): AggregateStats {        return AggregateStats(            totalCalls = totalCalls.get(),            successfulCalls = successfulCalls.get(),            failedCalls = failedCalls.get(),            currentMonthYear = currentMonthYear,            totalSpentThisMonth = getTotalSpentThisMonth(),        )    }    /**     * Manually reset all usage data (used by Settings → Privacy → Reset Stats).     */    fun reset() {        monthlyUsageByProvider.clear()        totalCalls.set(0L)        successfulCalls.set(0L)        failedCalls.set(0L)        currentMonthYear = computeMonthYear(Instant.now())    }    // ─── Internal ────────────────────────────────────────────────────────    private fun checkAndResetIfNewMonth() {        val now = computeMonthYear(Instant.now())        if (now != currentMonthYear) {            Timber.tag("NOUS.L4").i("Monthly reset: %s → %s", currentMonthYear, now)            monthlyUsageByProvider.clear()            currentMonthYear = now        }    }    private fun computeMonthYear(instant: Instant): String {        val date = instant.atZone(userTimezone).toLocalDate()        return "${date.year}-${date.monthValue.toString().padStart(2, '0')}"    }    /**     * Usage for one provider in one month.     */    data class MonthlyUsage(        val providerId: String,        val monthYear: String,        val inputTokens: Long = 0L,        val outputTokens: Long = 0L,        val costUsd: Float = 0f,        val successfulCalls: Long = 0L,        val failedCalls: Long = 0L,    ) {        fun addUsage(            inputTokens: Int,            outputTokens: Int,            costUsd: Float,            success: Boolean,        ): MonthlyUsage = copy(            inputTokens = this.inputTokens + inputTokens,            outputTokens = this.outputTokens + outputTokens,            costUsd = this.costUsd + costUsd,            successfulCalls = if (success) this.successfulCalls + 1 else this.successfulCalls,            failedCalls = if (!success) this.failedCalls + 1 else this.failedCalls,        )        val totalCalls: Long get() = successfulCalls + failedCalls    }    /**     * Aggregate stats across all providers and all time.     */    data class AggregateStats(        val totalCalls: Long,        val successfulCalls: Long,        val failedCalls: Long,        val currentMonthYear: String,        val totalSpentThisMonth: Float,    )}/** * Helper to compute LocalDate from epoch millis in a specific timezone. */internal fun epochMsToLocalDate(epochMs: Long, zoneId: ZoneId): LocalDate =    Instant.ofEpochMilli(epochMs).atZone(zoneId).toLocalDate()